let Recon = SigninLogs | where TimeGenerated > ago(7d) | where ResultType != "0" | summarize Attempts = count(), IPs = dcount(IPAddress) by UserPrincipalName | where Attempts > 10 | extend Phase = "1-Reconnaissance", Technique = "T1589 - Credential Gathering";
let InitialAccess = SigninLogs | where TimeGenerated > ago(7d) | where ResultType == "0" | where RiskLevelDuringSignIn in ("medium", "high") | summarize Attempts = count(), IPs = dcount(IPAddress) by UserPrincipalName | extend Phase = "2-Initial Access", Technique = "T1078 - Valid Accounts";
let CredAccess = SigninLogs | where TimeGenerated > ago(7d) | where ResultType == "50074" | summarize Attempts = count(), IPs = dcount(IPAddress) by UserPrincipalName | where Attempts >= 5 | extend Phase = "3-Credential Access", Technique = "T1621 - MFA Bombing";
union Recon, InitialAccess, CredAccess
| project Phase, Technique, UserPrincipalName, Attempts, IPs
| order by Phase asc, Attempts desc

let UnsignedBinds = toscalar(Event | where TimeGenerated > ago(7d) | where EventLog == "Directory Service" | where EventID == 2889 | count);
let ClearTextBinds = toscalar(Event | where TimeGenerated > ago(7d) | where EventLog == "Directory Service" | where EventID == 2887 | count);
let ExpensiveQueries = toscalar(Event | where TimeGenerated > ago(7d) | where EventLog == "Directory Service" | where EventID == 1644 | count);
let Score = 100 -
    (case(UnsignedBinds > 1000, 30, UnsignedBinds > 100, 20, UnsignedBinds > 10, 10, 0) +
    case(ClearTextBinds > 100, 30, ClearTextBinds > 10, 20, ClearTextBinds > 0, 10, 0) +
    case(ExpensiveQueries > 100, 20, ExpensiveQueries > 10, 10, 0));
print SecurityScore = Score, UnsignedBinds = UnsignedBinds, ClearTextBinds = ClearTextBinds, ExpensiveQueries = ExpensiveQueries,
    Grade = case(Score >= 90, "A", Score >= 80, "B", Score >= 70, "C", Score >= 60, "D", "F")

let EmailUsers = AlertEvidence | where TimeGenerated > ago(7d) | join kind=inner (AlertInfo | where TimeGenerated > ago(7d) | where ServiceSource has_any ("Office 365", "MDO")) on AlertId | where isnotempty(AccountUpn) | summarize EmailAlerts = dcount(AlertId) by AccountUpn;
let IdUsers = AlertEvidence | where TimeGenerated > ago(7d) | join kind=inner (AlertInfo | where TimeGenerated > ago(7d) | where ServiceSource has_any ("Azure AD", "Microsoft Entra", "MCAS")) on AlertId | where isnotempty(AccountUpn) | summarize IdAlerts = dcount(AlertId) by AccountUpn;
EmailUsers | join kind=inner IdUsers on AccountUpn
| extend TotalAlerts = EmailAlerts + IdAlerts
| order by TotalAlerts desc

// NOTE: Adjust start and end dates to your reporting period
let start = datetime(2025-01-01);
let end   = datetime(2026-01-01);
SecurityIncident
| where TimeGenerated >= start and TimeGenerated < end
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| where Status == "Closed" and isnotempty(ClosedTime)
| where ClosedTime >= start and ClosedTime < end
| summarize ClosedUnique = count() by Title
| top 10 by ClosedUnique desc

// NOTE: Replace 'PrivilegedGroups' with your Sentinel Watchlist name
// NOTE: Ensure the Watchlist has a column matching SearchKey that contains group display names
let PrivGroups =
    _GetWatchlist('PrivilegedGroups')
    | project GroupName = tostring(SearchKey);
AuditLogs
| where TimeGenerated > ago(7d)
| where OperationName == "Add member to group"
| where TargetResources[0].type == "User"
| extend GroupName = tostring(
        parse_json(
            tostring(
                parse_json(tostring(TargetResources[0].modifiedProperties))[1].newValue
            )
        )
    )
| where GroupName in (PrivGroups)
| extend User = tostring(TargetResources[0].userPrincipalName)
| summarize
    ['Count of Users Added'] = dcount(User),
    ['List of Users Added'] = make_set(User)
    by GroupName
| sort by GroupName asc

let window = 30d;
let Alerts =
    SecurityAlert
    | where TimeGenerated > ago(window)
    | extend
        SystemAlertId = tostring(SystemAlertId),
        RuleId = tostring(parse_json(ExtendedProperties)["Analytic Rule Ids"]);
let AlertsByRule =
    Alerts
    | summarize AlertCount = count(), RuleName = any(AlertName) by RuleId;
let AlertsInIncidents =
    SecurityIncident
    | where TimeGenerated > ago(window)
    | mv-expand AlertIds
    | extend SystemAlertId = tostring(AlertIds)
    | project SystemAlertId, IncidentNumber;
let IncidentMapping =
    Alerts
    | join kind=inner AlertsInIncidents on SystemAlertId
    | summarize IncidentsFromRule = dcount(IncidentNumber) by RuleId;
AlertsByRule
| join kind=leftouter IncidentMapping on RuleId
| extend IncidentsFromRule = coalesce(IncidentsFromRule, 0)
| extend AlertToIncidentRatio = round(todouble(IncidentsFromRule) / todouble(AlertCount), 3)
| extend PctAlertsOrphaned = round(100.0 * (AlertCount - IncidentsFromRule) / AlertCount, 1)
| where AlertCount >= 10
| where PctAlertsOrphaned >= 80
| project RuleName, RuleId, AlertCount, IncidentsFromRule, AlertToIncidentRatio, PctAlertsOrphaned
| order by AlertCount desc

let LookbackPeriod = 30d;

// Accounts/hosts explicitly excluded from alerting (known legacy exceptions)
let LegacyNTLMExclusions = dynamic([
  // Add confirmed legacy systems that require NTLMv1 for business reasons:
  // "legacy-print01", "old-scanner-dev"
  ""
]);

// ──────────────────────────────────────────────────────────────
// PART 1 - NTLMv1 Logon Events
//  LmPackageName values:
//   "LM"             → LAN Manager (prehistoric - NT 3.x era)
//   "NTLM V1"           → NTLMv1 (crackable offline in seconds)
//   "NTLM V1 with Client Challenge"→ NTLMv1 with ESS - still crackable
//   "NTLM V2"           → NTLMv2 (acceptable)
// ──────────────────────────────────────────────────────────────
let NTLMv1Events = SecurityEvent
  | where TimeGenerated >= ago(LookbackPeriod)
  | where EventID == 4624
  | where AuthenticationPackageName =~ "NTLM"
  | where LmPackageName in ("LM", "NTLM V1", "NTLM V1 with Client Challenge")
  | where LogonType in (3, 9, 10)    // Network, NewCredentials, RemoteInteractive
  | where not(WorkstationName in~ (LegacyNTLMExclusions))
  | extend
    Account     = tolower(strcat(TargetDomainName, "\\", TargetUserName)),
    SourceHost    = WorkstationName,
    DestHost     = Computer,
    SourceIP     = IpAddress,
    NTLMVersion   = LmPackageName,
    IsMachineAccount = TargetUserName endswith "$",
    LogonTypeName  = case(
      LogonType == 3, "Network",
      LogonType == 9, "NewCredentials",
      LogonType == 10, "RemoteInteractive",
      tostring(LogonType));

// ──────────────────────────────────────────────────────────────
// PART 2 - Per-Account NTLMv1 Summary with Risk Scoring
// ──────────────────────────────────────────────────────────────
let NTLMv1Summary = NTLMv1Events
  | summarize
    FirstSeen     = min(TimeGenerated),
    LastSeen      = max(TimeGenerated),
    TotalEvents    = count(),
    UniqueDestHosts  = dcount(DestHost),
    UniqueSourceIPs  = dcount(SourceIP),
    DestHosts     = make_set(DestHost, 20),
    SourceIPs     = make_set(SourceIP, 10),
    SourceHosts    = make_set(SourceHost, 10),
    NTLMVersions    = make_set(NTLMVersion),
    LogonTypes     = make_set(LogonTypeName),
    IsMachineAccount  = max(toint(IsMachineAccount))
    by Account
  | extend
    RiskScore = (
      iff(IsMachineAccount == 1,     50, 0) + // Machine account = Silver Ticket risk
      iff(UniqueDestHosts >= 5,      30, 0) + // Spreading across many hosts = lateral movement
      iff(UniqueSourceIPs >= 3,      20, 0) + // Multiple sources = relay or broad misconfiguration
      iff(NTLMVersions has "LM",     20, 0) + // Pure LM = worst case
      iff(TotalEvents >= 100,       15, 0)  // High volume
    ),
    RiskLevel = case(
      IsMachineAccount == 1,
        "Critical - Machine account NTLMv1 enables Silver Ticket without cracking (NT hash exposed)",
      UniqueDestHosts >= 10,
        "High - NTLMv1 lateral movement spread across 10+ hosts",
      UniqueDestHosts >= 3,
        "High - NTLMv1 spread across multiple hosts",
      TotalEvents >= 50,
        "Medium - High-volume NTLMv1 from single source",
      "Low - NTLMv1 detected, investigate legacy system"
    );

// ──────────────────────────────────────────────────────────────
// PART 3 - NTLM-Only Accounts (no Kerberos observed - pure NTLM)
//  These accounts have either:
//   - No SPN set (old service accounts)
//   - msDS-SupportedEncryptionTypes = NTLM only
//   - Forced NTLM by relay attack (source is attacker's tool)
// ──────────────────────────────────────────────────────────────
let KerberosAccounts = SecurityEvent
  | where TimeGenerated >= ago(LookbackPeriod)
  | where EventID == 4624
  | where AuthenticationPackageName =~ "Kerberos"
  | where LogonType in (3, 9, 10)
  | summarize KerberosLogons = count() by AccountKey = tolower(TargetUserName);

let AllNTLMAccounts = SecurityEvent
  | where TimeGenerated >= ago(LookbackPeriod)
  | where EventID == 4624
  | where AuthenticationPackageName =~ "NTLM"
  | where LogonType in (3, 9, 10)
  | where TargetUserName !in~ ("ANONYMOUS LOGON", "IUSR", "IWAN_")
  | where not(WorkstationName in~ (LegacyNTLMExclusions))
  | summarize
    NTLMLogons    = count(),
    UniqueTargets  = dcount(Computer),
    Targets     = make_set(Computer, 15),
    SourceIPs    = make_set(IpAddress, 10),
    NTLMPackages   = make_set(LmPackageName),
    FirstSeen    = min(TimeGenerated),
    LastSeen     = max(TimeGenerated)
    by AccountKey = tolower(TargetUserName), Domain = TargetDomainName
  | join kind=leftouter (KerberosAccounts) on AccountKey
  | extend
    KerberosLogons  = coalesce(KerberosLogons, 0),
    TotalAuth     = NTLMLogons + coalesce(KerberosLogons, 0)
  | extend
    NTLMPercent    = round(toreal(NTLMLogons) / toreal(NTLMLogons + max_of(KerberosLogons,1)) * 100, 1),
    AuthProfile    = case(
      KerberosLogons == 0,        "NTLM-Only (no Kerberos ever observed)",
      NTLMLogons > KerberosLogons * 3,  "Predominantly NTLM (>75%)",
      NTLMLogons > KerberosLogons,    "Majority NTLM",
                        "Mixed NTLM+Kerberos"
    )
  | where NTLMLogons > 5
  | extend
    DowngradeRisk = case(
      KerberosLogons == 0 and NTLMLogons > 20,
        "High - Pure NTLM account, no Kerberos baseline established",
      NTLMPackages has "NTLM V1",
        "High - NTLMv1 detected within NTLM traffic",
      NTLMPercent >= 80,
        "Medium - Predominantly NTLM, possible downgrade or legacy config",
      "Low - Occasional NTLM alongside Kerberos"
    );

// ──────────────────────────────────────────────────────────────
// PART 4 - Daily NTLMv1 Trend (for remediation tracking)
// ──────────────────────────────────────────────────────────────
let DailyTrend = NTLMv1Events
  | summarize
    NTLMv1Count   = count(),
    UniqueAccounts = dcount(Account),
    UniqueHosts   = dcount(DestHost),
    LMCount     = countif(NTLMVersion == "LM"),
    NTLMv1Count_ESS = countif(NTLMVersion has "Client Challenge")
    by Day = bin(TimeGenerated, 1d)
  | order by Day desc;

// ──────────────────────────────────────────────────────────────
// PRIMARY OUTPUT - NTLMv1 accounts sorted by risk
// Comment/uncomment the sub-query at the bottom to switch views
// ──────────────────────────────────────────────────────────────
NTLMv1Summary
| project-reorder
  RiskLevel, Account,
  FirstSeen, LastSeen,
  TotalEvents, UniqueDestHosts, UniqueSourceIPs,
  DestHosts, SourceIPs, SourceHosts,
  NTLMVersions, LogonTypes, IsMachineAccount, RiskScore
| order by RiskScore desc, TotalEvents desc

// ── Alternate views (comment out primary output above and run one of these) ──
// --- NTLM-Only account profile ---
// AllNTLMAccounts
// | project-reorder
//   AccountKey, Domain, DowngradeRisk, AuthProfile,
//   NTLMLogons, KerberosLogons, NTLMPercent,
//   UniqueTargets, Targets, SourceIPs, NTLMPackages,
//   FirstSeen, LastSeen
// | order by NTLMLogons desc

// --- Daily trend for exec reporting ---
// DailyTrend

﻿// Hunt   : Hunt - GPU and High-Compute VM Deployment History (90d)
// Tactics : Impact
// MITRE  : T1496
// Purpose : Inventory all successful GPU/high-compute VM deployments over the past 90 days. Use to baseline legitimate deployers before tuning Rule-01, and to investigate potential cryptojacking campaigns.
//==========================================================================================

let GPUSKUs = dynamic(["Standard_NC", "Standard_NV", "Standard_ND", "Standard_NP", "Standard_HB", "Standard_HC"]);
AzureActivity
| where TimeGenerated > ago(90d)
| where OperationNameValue has_any ("VIRTUALMACHINES/WRITE", "VIRTUALMACHINESCALESETS/WRITE")
| where ActivityStatusValue =~ "Success"
| where Properties has_any (GPUSKUs)
| project TimeGenerated, Caller, CallerIpAddress, SubscriptionId, ResourceGroup, ResourceId, Properties
| extend SKUHint = extract(@'Standard_(?:NC|NV|ND|NP|HB|HC)[^"]*', 0, Properties)
| order by TimeGenerated desc

﻿// Hunt   : Hunt - Diagnostic Settings Change Timeline per Resource (90d)
// Tactics : DefenseEvasion
// MITRE  : T1562.008
// Purpose : Show the full create/update/delete history of diagnostic settings per resource. Use to identify resources that were permanently unmonitored by correlating delete events with no subsequent write.
//==========================================================================================

AzureActivity
| where TimeGenerated > ago(90d)
| where OperationNameValue has "DIAGNOSTICSETTINGS"
| where ActivityStatusValue =~ "Success"
| project TimeGenerated, Operation = OperationNameValue, Caller, ResourceId, CallerIpAddress, SubscriptionId, ResourceGroup
| extend IsDelete = Operation has "DELETE"
| order by ResourceId asc, TimeGenerated asc

﻿// Hunt   : Hunt - Azure Automation Runbook Create, Modify, Publish History (90d)
// Tactics : Execution,Persistence
// MITRE  : T1059.009
// Purpose : Full history of Automation Account object changes. Use to identify newly created runbooks, unexpected content changes, and newly added webhooks (used for C2 callbacks). Correlate Caller with Rule-05 first-time-caller alerts.
//==========================================================================================

AzureActivity
| where TimeGenerated > ago(90d)
| where OperationNameValue has "AUTOMATION"
| where OperationNameValue has_any ("RUNBOOKS", "WEBHOOKS", "SCHEDULES", "VARIABLES", "MODULES")
| where ActivityStatusValue =~ "Success"
| project TimeGenerated, Caller, Operation = OperationNameValue, ResourceName = tostring(split(ResourceId, "/")[-1]), ResourceId, CallerIpAddress, ResourceGroup, SubscriptionId
| order by TimeGenerated desc
